		t.Fatal(err)
	}
	reexeced := false
	service := testService(home, nil)
	service.herdrContext = func() bool { return false }
	service.reexecUpdate = func(string, []string, []string) error {
		reexeced = true
		return nil
	}
	code, output := runCLI(t, service, "watch", "--timeout", "5000")
